using System;using System.IO;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace EanEtikety {
public partial class MainForm {
 EditHistory history;WorkspaceStore workspace;readonly Timer recoveryTimer=new Timer();bool historyApplying,historyReading;string savedDocument;HeaderActionButton undoButton,redoButton;UiContextMenuStrip featureMenu;
 BatchSetup batchSetup=new BatchSetup();List<ElementMeta> elementMetadata=new List<ElementMeta>();List<VariableField> variables=new List<VariableField>();SheetLayout sheetLayout=new SheetLayout();bool hideBarcode;
 void InitializeWorkspace(){datePreviewTimer.Tick+=delegate{RefreshDatePreview();};datePreviewTimer.Start();history=new EditHistory();history.Reset(Read());savedDocument=ProjectXml.Encode(Read());try{workspace=new WorkspaceStore(startupPath);}catch(Exception ex){status.Text=ex.Message;}
  undoButton=HeaderAction("Späť",HeaderIcon.Undo,"Ctrl+Z",delegate{StepHistory(false);});redoButton=HeaderAction("Znova",HeaderIcon.Redo,"Ctrl+Y",delegate{StepHistory(true);});headerCommands.Controls.Add(undoButton);headerCommands.Controls.Add(redoButton);
  featureMenu=new UiContextMenuStrip();var features=HeaderAction("Nástroje",HeaderIcon.Tools,null,delegate{});features.Click+=delegate{BuildFeatureMenu();featureMenu.Show(features,0,features.Height);};headerCommands.Controls.Add(features);
  Shown+=delegate{OfferRecovery();};FormClosed+=delegate{if(workspace!=null)workspace.Clean();};Disposed+=delegate{datePreviewTimer.Dispose();recoveryTimer.Dispose();if(workspace!=null)workspace.Dispose();featureMenu.Dispose();};recoveryTimer.Tick+=delegate{AutoSave();};RestartRecovery();RefreshHistory();ApplyTheme();UpdateToolbarLayout();
 }
 void RestartRecovery(){recoveryTimer.Stop();if(workspace!=null&&workspace.Options.AutoSave){recoveryTimer.Interval=workspace.Options.IntervalSeconds*1000;recoveryTimer.Start();}}
 void AutoSave(){if(!dirty||preview.IsDragging||workspace==null)return;try{CommitInspectorIfFocused();workspace.SaveRecovery(Read(),settingsPath);}catch(Exception ex){status.Text=Loc.T("Obnovovaciu kópiu sa nepodarilo uložiť")+": "+ex.Message;}}
 void CommitInspectorIfFocused(){if(inspectText!=null&&inspectText.ContainsFocus)CommitInspector();}
 void OfferRecovery(){if(workspace==null)return;workspace.Recoverable(delegate(string path,RecoveryDocument document){var answer=UiMessageBox.Show(this,Loc.T("Obnoviť rozpracovaný projekt?")+"\r\n"+(document.OriginalPath??Loc.T("Nová etiketa"))+"\r\n"+document.SavedUtc.ToLocalTime(),Loc.T("Obnova práce"),MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Yes){Apply(document.Label);settingsPath=document.OriginalPath;ResetHistory(false);Changed(this,EventArgs.Empty);workspace.SaveRecovery(Read(),settingsPath);File.Delete(path);}else if(answer==DialogResult.No)File.Delete(path);},delegate(string error){status.Text=Loc.T("Obnovovaciu kópiu sa nepodarilo načítať")+": "+error;});}
 void TrackHistory(){if(history==null||historyApplying||historyReading||loading||preview.IsDragging||preview.Restoring)return;historyReading=true;try{history.Record(Read());RefreshHistory();}catch(Exception ex){System.Diagnostics.Trace.WriteLine(ex);}finally{historyReading=false;}}
 void RefreshHistory(){if(undoButton!=null){undoButton.Enabled=history.CanUndo;redoButton.Enabled=history.CanRedo;}}
 void ResetHistory(bool saved){if(history==null)return;history.Reset(Read());savedDocument=saved?ProjectXml.Encode(Read()):null;RefreshHistory();}
 void StepHistory(bool redo){if(preview.IsDragging)return;CommitInspectorIfFocused();timer.Stop();TrackHistory();var s=redo?history.Redo():history.Undo();if(s==null)return;historyApplying=true;try{Apply(s);dirty=ProjectXml.Encode(Read())!=savedDocument;UpdateWindowTitle();}finally{historyApplying=false;}RefreshHistory();}
 void DocumentSaved(){if(history==null)return;TrackHistory();savedDocument=ProjectXml.Encode(Read());if(workspace!=null){workspace.Remember(settingsPath);workspace.Clean();}}
 void DocumentOpened(){if(history==null)return;ResetHistory(true);if(workspace!=null&&settingsPath!=null)workspace.Remember(settingsPath);}
 void ChangeDocument(Action<LabelSettings> action){CommitInspectorIfFocused();TrackHistory();var s=Read();action(s);int selected=preview.SelectedIndex;Apply(s);dirty=true;preview.SelectElement(Elements.Indices(s).Contains(selected)?selected:-2);UpdateWindowTitle();TrackHistory();}
 Form FeatureForm(string title,int width,int height){var f=new Form{Text=Loc.T(title),Font=Font,ClientSize=new Size(width,height),MinimumSize=new Size(Math.Min(width,420),Math.Min(height,320)),StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false,AutoScaleMode=AutoScaleMode.Dpi};return f;}
 TableLayoutPanel FeatureStack(Form form){var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(14)};form.Controls.Add(scroll);var stack=Stack();scroll.Controls.Add(stack);return stack;}
 NumericUpDown Number(TableLayoutPanel stack,string name,decimal value,decimal min,decimal max,int decimals){var c=new NumericUpDown{Minimum=min,Maximum=max,DecimalPlaces=decimals,Value=Math.Min(max,Math.Max(min,value))};StackField(stack,Loc.T(name),c);return c;}
 TextBox Input(TableLayoutPanel stack,string name,string value){var c=new TextBox{Text=value??""};StackField(stack,Loc.T(name),c);return c;}
 CheckBox Check(TableLayoutPanel stack,string name,bool value){var c=new CheckBox{Text=Loc.T(name),Checked=value,AutoSize=true};StackAdd(stack,c);return c;}
 ComboBox Choice(TableLayoutPanel stack,string name,string[] choices,int selected){var c=new ModernComboBox{DropDownStyle=ComboBoxStyle.DropDownList};foreach(string x in choices)c.Items.Add(Loc.T(x));c.SelectedIndex=Math.Max(0,selected);StackField(stack,Loc.T(name),c);return c;}
 void AddAccept(Form f,TableLayoutPanel stack,Action action){var ok=Btn(Loc.T("Použiť"),delegate{try{action();f.DialogResult=DialogResult.OK;}catch(Exception ex){Error(ex);}});var cancel=Btn(Loc.T("Zrušiť"),delegate{f.DialogResult=DialogResult.Cancel;});var row=new FlowLayoutPanel{AutoSize=true};row.Controls.Add(ok);row.Controls.Add(cancel);StackAdd(stack,row);f.AcceptButton=ok;f.CancelButton=cancel;ApplyColors(f);}
 void BuildFeatureMenu(){featureMenu.Items.Clear();featureMenu.Renderer=new ToolStripProfessionalRenderer(new StudioMenuColors(dark));featureMenu.ForeColor=StudioTheme.Text(dark);Action<string,Action> add=(text,action)=>featureMenu.Items.Add(Loc.T(text),null,delegate{try{action();}catch(Exception ex){Error(ex);}});
  add("Šablóny a nedávne projekty",ShowLibrary);add("Automatické ukladanie",RecoveryPreferences);add("Dávka a premenné",ShowBatch);add("Samolepiace hárky",EditSheet);add("Vložiť obrázok",AddImage);add("Pridať QR / Data Matrix",AddMatrix);add("Pridať čiarový kód",AddBarcodeObject);add("Rozloženie a výber",ShowArrange);add("Kontrola etikety",ShowChecks);
 }
 void RecoveryPreferences(){if(workspace==null)return;using(var f=FeatureForm("Automatické ukladanie",420,270)){var p=FeatureStack(f);var enabled=Check(p,"Automatické ukladanie",workspace.Options.AutoSave);var interval=Number(p,"Interval (sekundy)",workspace.Options.IntervalSeconds,10,3600,0);AddAccept(f,p,delegate{workspace.Options.AutoSave=enabled.Checked;workspace.Options.IntervalSeconds=(int)interval.Value;workspace.SaveOptions();RestartRecovery();});f.ShowDialog(this);}}
 void ShowLibrary(){if(workspace==null)return;using(var f=FeatureForm("Šablóny a nedávne projekty",800,620))using(var images=new ImageList{ImageSize=new Size(160,110),ColorDepth=ColorDepth.Depth32Bit}){
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(12)};root.RowStyles.Add(new RowStyle(SizeType.Percent,65));root.RowStyles.Add(new RowStyle(SizeType.Percent,35));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));f.Controls.Add(root);
  var list=new ListView{Dock=DockStyle.Fill,View=View.LargeIcon,LargeImageList=images,MultiSelect=false};root.Controls.Add(list,0,0);var recent=new ListBox{Dock=DockStyle.Fill,HorizontalScrollbar=true};root.Controls.Add(recent,0,1);foreach(string path in workspace.Options.Recent)recent.Items.Add(path);
  var thumbnails=new List<Bitmap>();Action refresh=delegate{list.Items.Clear();images.Images.Clear();foreach(var old in thumbnails)old.Dispose();thumbnails.Clear();foreach(string file in Directory.GetFiles(workspace.TemplatesPath,"*.ean.xml")){try{var s=Engine.Load(file);using(var scene=VectorArt.Build(s))using(var b=new Bitmap(160,110))using(var g=Graphics.FromImage(b)){g.Clear(Color.White);float scale=Math.Min(156/(float)s.Width,106/(float)s.Height);scene.Draw(g,new RectangleF(2,2,(float)s.Width*scale,(float)s.Height*scale),false);var thumbnail=(Bitmap)b.Clone();thumbnails.Add(thumbnail);images.Images.Add(thumbnail);}list.Items.Add(new ListViewItem(Path.GetFileName(file).Replace(".ean.xml",""),images.Images.Count-1){Tag=file});}catch(Exception ex){list.Items.Add(new ListViewItem(Path.GetFileName(file)+" — "+Loc.T("Chyba")){Tag=file,ToolTipText=ex.Message});}}};
  if(Directory.GetFiles(workspace.TemplatesPath,"*.ean.xml").Length==0){foreach(double width in new[]{60d,100d}){var s=StartupLayout.Create(new StartupProfile{Width=width,Height=width==60?45:60});ProjectXml.Save(Path.Combine(workspace.TemplatesPath,"Etiketa "+width+".ean.xml"),s);}}refresh();
  var row=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true};root.Controls.Add(row,0,2);
  row.Controls.Add(Btn(Loc.T("Otvoriť šablónu"),delegate{if(list.SelectedItems.Count==0||!CanDiscard())return;try{var s=Engine.Load((string)list.SelectedItems[0].Tag);Apply(s);settingsPath=null;ResetHistory(false);Changed(this,EventArgs.Empty);f.Close();}catch(Exception ex){Error(ex);}}));
  row.Controls.Add(Btn(Loc.T("Uložiť ako šablónu"),delegate{using(var name=FeatureForm("Názov šablóny",400,220)){var p=FeatureStack(name);var input=Input(p,"Názov šablóny",Loc.T("Moja etiketa"));AddAccept(name,p,delegate{if(string.IsNullOrWhiteSpace(input.Text)||input.Text.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new Exception(Loc.T("Neplatný názov"));var path=Path.Combine(workspace.TemplatesPath,input.Text.Trim()+".ean.xml");if(File.Exists(path))throw new Exception(Loc.T("Názov už existuje"));var s=Read();Engine.Save(path,s);refresh();});name.ShowDialog(f);}}));
  row.Controls.Add(Btn(Loc.T("Odstrániť šablónu"),delegate{if(list.SelectedItems.Count>0&&UiMessageBox.Show(f,Loc.T("Odstrániť šablónu?"),Loc.T("Šablóny"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){File.Delete((string)list.SelectedItems[0].Tag);refresh();}}));
  row.Controls.Add(Btn(Loc.T("Otvoriť nedávny projekt"),delegate{if(recent.SelectedItem==null)return;string path=(string)recent.SelectedItem;if(!File.Exists(path)){UiMessageBox.Show(f,Loc.T("Súbor sa nenašiel")+": "+path,Loc.T("Nedávne projekty"));workspace.Options.Recent.Remove(path);workspace.SaveOptions();recent.Items.Remove(path);return;}if(!CanDiscard())return;try{OpenImportedFile(path);f.Close();}catch(Exception ex){Error(ex);}}));ApplyColors(f);f.ShowDialog(this);foreach(var thumbnail in thumbnails)thumbnail.Dispose();
 }}
}
